<?php require 'config/database.php';require 'partials/functions.php';require_login();$uid=$_SESSION['user']['id'];$pid=(int)$_POST['product_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');$st=$conn->prepare('INSERT INTO reviews(user_id,product_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)');$st->bind_param('iiis',$uid,$pid,$rating,$comment);$st->execute();header('Location: product.php?id='.$pid);
